package wifihaven.api.unit

import wifihaven.api.db.DeviceNames
import zio.test.*

/**
 * #2926: the placeholder-name rule that ingest, `renameIfAutoGenerated` and the identify view's
 * `sentName` all share. The legacy "unknown" is the case the SPA's own copy of the rule once
 * missed.
 */
object DeviceNamesSpec extends ZIOSpecDefault {
  def spec = suite("DeviceNames")(
    test("the generated name and the legacy name are placeholders") {
      assertTrue(
        DeviceNames.isPlaceholder(DeviceNames.generated("aa:bb:cc:11:22:33")),
        DeviceNames.generated("aa:bb:cc:11:22:33") == "device-112233",
        DeviceNames.isPlaceholder("unknown"),
      )
    },
    test("a name a device sent is not a placeholder") {
      assertTrue(
        !DeviceNames.isPlaceholder("Roku-Living-Room"),
        !DeviceNames.isPlaceholder("device-livingroom"),
        !DeviceNames.isPlaceholder("Unknown-TV"),
      )
    },
  )
}
